INSERT INTO content.blog_posts
  (slug,title,excerpt,category,image,author,author_role,read_min,body,featured,status,published_at)
VALUES
  ('spacing-and-retrieval-practice', 'Why Spacing and Retrieval Practice Beat Re-Reading Every Time', 'Decades of cognitive science research point to two techniques that dramatically outperform passive review. Here''s how NaNa builds them into every session.', 'Learning Science', 'https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?auto=format&fit=crop&w=1200&q=80', 'Dr. Amara Osei', 'Head of Learning Science', 7, '[{"type":"p","text":"Most students study the way they were taught to: read the chapter, highlight the important bits, then read it again the night before the exam. It feels productive. The pages look busy with colour, the material feels familiar, and familiarity is easily mistaken for mastery. Unfortunately, decades of research in cognitive science tell us this is one of the least efficient ways to learn anything durably."},{"type":"h","text":"The familiarity trap"},{"type":"p","text":"When you re-read a passage, your brain recognises the words and concludes, \"I know this.\" But recognition is not recall. The real test of learning is whether you can retrieve the information when the page is closed — and re-reading does almost nothing to build that ability."},{"type":"quote","text":"Recognition is not recall. The page being familiar tells you nothing about whether you can produce the answer when it counts."},{"type":"h","text":"Retrieval practice: the testing effect"},{"type":"p","text":"The single most reliable finding in the learning sciences is that the act of retrieving information from memory strengthens that memory far more than re-studying it. Every time you successfully pull a fact out of your head, the pathway to it gets stronger and easier to travel next time."},{"type":"list","items":["Close the book and try to write down everything you remember before checking.","Answer questions before you feel ready — the struggle is where the learning happens.","Use flashcards that force production, not just recognition."]},{"type":"h","text":"Spacing: why cramming fails"},{"type":"p","text":"The second pillar is spacing. Reviewing material across several days or weeks produces dramatically better long-term retention than the same amount of study crammed into one sitting. Each time you revisit a concept after partly forgetting it, you reload it more deeply."},{"type":"h","text":"How NaNa puts this to work"},{"type":"p","text":"NaNa schedules every concept you learn into a spaced-retrieval queue. Instead of asking you to re-read, your agent quizzes you at the precise moment you''re about to forget — turning revision into active recall and stretching reviews across optimal intervals. You don''t have to plan any of it; the science runs in the background while you focus on learning."}]'::jsonb, true, 'published', now())
