INSERT INTO content.blog_posts
  (slug,title,excerpt,category,image,author,author_role,read_min,body,featured,status,published_at)
VALUES
  ('adaptive-battle-mode', 'Introducing Adaptive Battle Mode: Your Agent Fights Smarter', 'Battle Mode just got a major upgrade. NaNa now analyses your weak spots in real time and targets exactly the concepts you need most.', 'Product', 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=1200&q=80', 'Kwame Asante', 'Product Lead', 4, '[{"type":"p","text":"Battle Mode has always been the most-loved feature in Akoro — pit your agent against a challenge and watch the knowledge fly. Today we''re shipping the biggest upgrade since launch: Adaptive Battle Mode."},{"type":"h","text":"What changed"},{"type":"p","text":"Previously, battles drew questions from a fixed pool for each topic. Adaptive Battle Mode replaces that with a live difficulty engine that reads your performance question-by-question and steers the fight toward the exact concepts you''re shakiest on."},{"type":"list","items":["Real-time weak-spot detection across every concept in the topic.","Difficulty that ramps up when you''re cruising and eases when you stall.","Post-battle reports that show precisely which ideas to revisit."]},{"type":"quote","text":"A battle is now a diagnostic. By the time it ends, NaNa knows your gaps better than you do."},{"type":"h","text":"Why it matters"},{"type":"p","text":"Practice only helps when it targets the edge of what you can do. Adaptive Battle Mode keeps you in that productive zone for the whole session, so every minute spent battling moves the needle. Update your app and challenge NaNa — it''s fighting smarter now."}]'::jsonb, false, 'published', now())
