INSERT INTO content.blog_posts
  (slug,title,excerpt,category,image,author,author_role,read_min,body,featured,status,published_at)
VALUES
  ('ghana-schools-stem-gap', 'How Ghanaian Secondary Schools Are Closing the STEM Gap with AI Tutors', 'Three schools. Eight months. A 23 % improvement in WAEC science scores. We break down what worked and what surprised us.', 'Education', 'https://images.unsplash.com/photo-1427504494785-3a9ca7044f45?auto=format&fit=crop&w=1200&q=80', 'Efua Mensah', 'Partnerships', 9, '[{"type":"p","text":"Last year we partnered with three secondary schools in the Greater Accra and Ashanti regions on a simple question: can a personal AI tutor measurably close the STEM attainment gap when class sizes routinely exceed fifty students?"},{"type":"h","text":"The setup"},{"type":"p","text":"Each participating student received an Akoro account with NaNa configured around their WAEC science syllabus. Teachers got a class dashboard showing where the cohort was struggling. We then tracked progress over two full terms."},{"type":"h","text":"The results"},{"type":"list","items":["23% average improvement in mock WAEC science scores across the three schools.","Students using NaNa for 20+ minutes a day improved nearly twice as fast.","Teachers reallocated class time away from re-explaining basics toward higher-order problem solving."]},{"type":"quote","text":"\"I finally have time to teach the hard parts, because NaNa handles the drilling,\" — one participating physics teacher."},{"type":"h","text":"What surprised us"},{"type":"p","text":"The biggest gains didn''t come from the strongest students — they came from the middle of the class, the learners who previously fell through the cracks of a fifty-student room. A personal agent gave them the patient, one-to-one attention that simply isn''t possible at that scale."},{"type":"h","text":"Where we go next"},{"type":"p","text":"We''re expanding the programme to twelve schools this year, with a focus on rural districts where access to specialist science teachers is thinnest. If you run a school and want to take part, our partnerships team would love to hear from you."}]'::jsonb, false, 'published', now())
