INSERT INTO content.blog_posts
  (slug,title,excerpt,category,image,author,author_role,read_min,body,featured,status,published_at)
VALUES
  ('agent-native-classroom-2030', 'The Agent-Native Classroom: What Education Looks Like in 2030', 'Every student has a personal AI agent that knows their learning history, adapts in real time, and never gives up. We''re building towards that future today.', 'AI & Future', 'https://images.unsplash.com/photo-1531482615713-2afd69097998?auto=format&fit=crop&w=1200&q=80', 'Nana Kofi Agyemang', 'Co-founder & CEO', 6, '[{"type":"p","text":"For two hundred years, the classroom has been built around a constraint: one teacher, many students. Everything from the pace of lessons to the design of exams flows from that single bottleneck. AI agents quietly remove it — and that changes everything downstream."},{"type":"h","text":"From one-to-many to one-to-one, at scale"},{"type":"p","text":"In an agent-native classroom, every student arrives with a personal agent that already knows their full learning history — what they''ve mastered, where they wobble, how they best take in new ideas. The teacher becomes a conductor of dozens of personalised journeys rather than a single broadcast signal."},{"type":"quote","text":"The teacher of 2030 isn''t replaced by AI — they''re amplified by it, freed to do the deeply human work machines can''t."},{"type":"h","text":"What the agent handles"},{"type":"list","items":["Continuous, low-stakes assessment that replaces the high-anxiety final exam.","Instant, patient re-explanation in whatever way each learner needs.","Spaced revision scheduled automatically around each student''s memory."]},{"type":"h","text":"What stays human"},{"type":"p","text":"Mentorship. Curiosity. The spark of a teacher who believes in a student more than they believe in themselves. Agents handle the mechanics of practice and recall so that human educators can pour their energy into the things only humans can do."},{"type":"h","text":"Building it now"},{"type":"p","text":"This isn''t a far-off vision. Every feature we ship — adaptive battles, spaced retrieval, the class dashboard — is a brick in that 2030 classroom. We''re building it one learner at a time, starting in Africa."}]'::jsonb, false, 'published', now())
