INSERT INTO content.blog_posts
  (slug,title,excerpt,category,image,author,author_role,read_min,body,featured,status,published_at)
VALUES
  ('abena-six-month-journey', 'From 42% to 78%: One Learner''s Six-Month Journey with NaNa', 'Abena failed her BECE mock twice. Six months later she passed with distinction. This is her story — in her own words.', 'Case Studies', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1200&q=80', 'Akoro Team', '', 5, '[{"type":"p","text":"When Abena first opened Akoro, she had already failed her BECE mock twice. Maths and integrated science were, in her words, \"subjects I had decided I was just bad at.\" Six months later she sat the real exam and passed with distinction. We asked her to tell the story herself."},{"type":"h","text":"Month one: starting over"},{"type":"p","text":"\"I didn''t trust it at first. Another app, another thing telling me to study. But NaNa didn''t lecture me — it asked me questions and waited. When I got something wrong it just showed me again, calmly, as many times as I needed.\""},{"type":"quote","text":"\"For the first time, getting an answer wrong didn''t feel like failing. It just felt like the next step.\""},{"type":"h","text":"Months two to four: the turn"},{"type":"p","text":"\"The battles became my favourite part. I''d challenge NaNa on the bus home. Slowly the questions I used to dread became the ones I wanted to fight. My mock score went from 42% to 61%.\""},{"type":"h","text":"The final stretch"},{"type":"list","items":["Twenty minutes of spaced revision every morning before school.","Battle Mode on her weakest topics three evenings a week.","A class dashboard her teacher used to give her targeted help."]},{"type":"h","text":"Distinction"},{"type":"p","text":"\"When the results came I read my name three times. 78%. Distinction in science. I''m not ''just bad at'' anything anymore — I just hadn''t found the right way to practise.\" Abena is now helping younger students at her school get started with NaNa."}]'::jsonb, false, 'published', now())
