INSERT INTO content.blog_posts
  (slug,title,excerpt,category,image,author,author_role,read_min,body,featured,status,published_at)
VALUES
  ('interleaving-study-strategy', 'Interleaving: The Counterintuitive Study Strategy That Actually Works', 'Mixing topics feels harder. Students score lower on immediate tests. Yet they retain far more a week later. Here''s the science behind interleaving.', 'Learning Science', 'https://images.unsplash.com/photo-1509228627152-72ae9ae6848d?auto=format&fit=crop&w=1200&q=80', 'Dr. Amara Osei', 'Head of Learning Science', 8, '[{"type":"p","text":"Imagine two students preparing for a maths exam. One practises twenty algebra problems, then twenty geometry problems, then twenty calculus problems — neatly blocked by topic. The other shuffles all sixty together in random order. Who learns more? The research says, overwhelmingly, the second student. Yet almost everyone studies like the first."},{"type":"h","text":"What is interleaving?"},{"type":"p","text":"Interleaving means mixing different types of problems or topics within a single study session, rather than practising one kind to mastery before moving on. It feels harder and slower — and that''s precisely why it works."},{"type":"quote","text":"Blocked practice feels great and teaches little. Interleaving feels hard and teaches a lot. Our intuitions about studying are almost exactly backwards."},{"type":"h","text":"Why the discomfort helps"},{"type":"p","text":"When problems are blocked, you already know which method to apply before you read the question. Interleaving forces you to first identify what kind of problem you''re facing — the exact skill you need on a real exam, where questions arrive in no particular order."},{"type":"list","items":["You learn to discriminate between problem types, not just execute procedures.","Repeatedly reloading different methods strengthens each one.","Performance feels worse during practice but is far higher when it counts."]},{"type":"h","text":"The catch"},{"type":"p","text":"Because interleaving makes practice feel harder, students abandon it — they see lower scores in the moment and conclude it isn''t working. This is the central paradox of learning: the strategies that feel most effective are often the least, and vice versa."},{"type":"h","text":"How NaNa interleaves for you"},{"type":"p","text":"NaNa automatically blends topics in your practice sessions and battles, so you''re always discriminating between problem types rather than running on autopilot. You get the proven benefits of interleaving without having to fight the very instincts that make it hard to stick with."}]'::jsonb, false, 'published', now())
